cd "$ARCHON_HORIZON_ROOT" && f=$(ls .archon-horizon/roadmap/items/ 2>/dev/null | grep -i "AJC.rr" | head -3); echo "files: $f"; python3 - <<'EOF'
import glob,yaml,sys
for p in glob.glob('.archon-horizon/roadmap/items/*'):
    try: d=yaml.safe_load(open(p))
    except Exception: continue
    if isinstance(d,dict) and d.get('name')=='AJC.rr':
        print('PATH',p,'status',d.get('status'))
        s=d.get('summary','')
        print(s[2100:4200])
EOF

cd /home/axel/LeanAlgebraicGeometry-Horizon && "$HORIZON_BIN" inbox list --status open --kind memory --limit 200 --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin); items=d.get('items',d)
print('memory open:',len(items))
for it in items:
    md=it.get('metadata') or {}
    prov=md.get('provenance') or {}
    body=it.get('body','')
    print(it.get('id'), '|', prov.get('task','?'), '| run',prov.get('run','?'), '|', (it.get('created_at') or '')[:16], '| persist' if '[persistent]' in body[:40] else '|        ', '|', body.split(chr(10))[0][:95])
"
